		#endregion

		public ZCurrencyManagerExplorer(ZBindingContext context)
		{
			InitializeComponent();

			this.Context = context;
			context.CollectionChanged += new EventHandler(Context_CollectionChanged);

			NodesByManager = new Hashtable();
			RelatedNodesByManager = new Hashtable();

			BuildTree();
		}

		protected override void Dispose(bool isNotFinalizing)
		{
			base.Dispose(isNotFinalizing);
			if (isNotFinalizing)
			{
				Context.CollectionChanged -= new EventHandler(Context_CollectionChanged);
			}
		}

		readonly ZBindingContext Context;

		[System.Diagnostics.CodeAnalysis.SuppressMessage("CargoWiseOne", "CW1161:ResGetStringAnalyzer", Justification = "Non-semantic text")]
		void BuildTree()
		{
			FieldInfo dataMemberField = null;
			FieldInfo weakReferenceField = null;

			foreach (DictionaryEntry entry in Context)
			{
				if (dataMemberField == null)
				{
					dataMemberField = entry.Key.GetType().GetField("dataMember", BindingFlags.Instance | BindingFlags.NonPublic);
					weakReferenceField = entry.Key.GetType().GetField("wRef", BindingFlags.Instance | BindingFlags.NonPublic);
				}

				var manager = ((BindingManagerBase)((WeakReference)entry.Value).Target);

				if (!RelatedNodesByManager.ContainsKey(manager))
				{
					var dataMember = dataMemberField.GetValue(entry.Key).ToString();
					var weakReference = (WeakReference)weakReferenceField.GetValue(entry.Key);
					var dataSource = weakReference.Target;

					var node = new TreeNode("{" + manager.GetType().Name + ", " + dataSource.GetType().Name + " + \"" + dataMember + "\"}");
					node.Nodes.Add("Position: " + manager.Position);
					node.Nodes.Add("Count: " + manager.Count);

					manager.PositionChanged += new EventHandler(Manager_Changed);
					manager.CurrentChanged += new EventHandler(Manager_Changed);

					RelatedNodesByManager.Add(manager, node.Nodes);
					NodesByManager.Add(manager, node);
				}
			}

			foreach (BindingManagerBase manager in NodesByManager.Keys)
			{
				var node = (TreeNode)NodesByManager[manager];
				var destination = NodeCollectionToAddTo(manager);
				if (!destination.Contains(node))
				{
					destination.Add(node);
				}
			}
		}

		TreeNodeCollection NodeCollectionToAddTo(BindingManagerBase manager)
		{
			if (manager.GetType().Name.IndexOf("Related") != -1)
			{
				var parentManagerField = manager.GetType().GetField("parentManager", BindingFlags.Instance | BindingFlags.NonPublic);
				var parentManager = (BindingManagerBase)parentManagerField.GetValue(manager);

				var nodes = (TreeNodeCollection)RelatedNodesByManager[parentManager];
				return nodes ?? TreeView.Nodes;
			}

			return TreeView.Nodes;
		}

		readonly Hashtable RelatedNodesByManager;
		readonly Hashtable NodesByManager;

		void Context_CollectionChanged(object sender, EventArgs e)
		{
			TreeView.Nodes.Clear();
			BuildTree();
		}

		[System.Diagnostics.CodeAnalysis.SuppressMessage("CargoWiseOne", "CW1161:ResGetStringAnalyzer", Justification = "Non-semantic text")]
		void Manager_Changed(object sender, EventArgs e)
		{
			var manager = sender as BindingManagerBase;
			var node = (TreeNode)NodesByManager[manager];
			// Check for TreeView disposal state before accessing TreeNode's properties, to prevent ObjectDisposeException during form disposal.
			if (!node.TreeView.IsDisposedOrHasDisposedParent())
			{
				node.Nodes[0].Text = "Position: " + manager.Position;
				node.Nodes[1].Text = Res.GetString("b1c4c9de-0f36-469b-b9f7-23c03e4474bb", "Count: {0}", manager.Count);
			}
		}
	}
